// STAGE 1 of the two-stage gate: is this page even up?
// Reads only verified Analyze quality fields (populated because enableQuality: true):
// quality.httpStatus, quality.isBlank, quality.hasCaptcha, with metadata.httpStatus as a
// fallback. enableSummary is off on purpose - a health check has no use for an AI summary,
// and this node runs 144 times a day per page.
// batchSize is 1, so .first() is the page currently in the loop.
const d = $input.first().json;
const row = $('Loop Over Watched Pages').first().json;
const q = d.quality || {};
const m = d.metadata || {};

const httpStatus =
  typeof q.httpStatus === 'number'
    ? q.httpStatus
    : typeof m.httpStatus === 'number'
      ? m.httpStatus
      : null;

// If the quality bundle came back empty (enableQuality switched off, or an account without
// Analyze access) we know NOTHING about this page. Reporting 'up' here would be an invention;
// an empty state makes Detect State Change keep the previous value instead.
const determinable =
  typeof q.httpStatus === 'number' ||
  typeof q.isBlank === 'boolean' ||
  typeof m.httpStatus === 'number';

const reasons = [];
if (httpStatus !== null && httpStatus >= 400) reasons.push('HTTP ' + httpStatus);
if (q.isBlank === true) reasons.push('rendered blank (no visible content)');
if (q.hasCaptcha === true) reasons.push('CAPTCHA / bot wall served to visitors');

let state = reasons.length ? 'down' : 'up';
if (!determinable) {
  state = '';
  reasons.push('availability undetermined - Analyze returned an empty quality object');
}

return [
  {
    json: {
      url: row.url,
      label: row.label || row.url,
      baselineUrl: row.baselineUrl || '',
      state,
      reason: reasons.join(' · '),
      httpStatus,
      mismatchPercentage: '',
      diffLink: '',
      visualCheck: 'not-run',
      screenshotLink: (d.screenshot && d.screenshot.link) || '',
    },
  },
];

// STAGE 2, and it only ever runs on a page stage 1 already proved is up. Pixel-comparing a
// page that is down would spend a Compare call to rediscover the 503 stage 1 reported.
// summary.mismatchPercentage is a 0-100 PERCENTAGE, not a 0-1 ratio. 10% is a layout-drift
// band: text edits measure ~0.01%, a broken stylesheet or a collapsed hero measures tens of
// percent. Lower it to 0 for pages where one character matters (pricing, legal text).
const VISUAL_DRIFT_PERCENT = 10;

const d = $input.first().json;
const stage1 = $('Evaluate Availability').first().json;
const summary = d.summary || {};
const mismatch =
  typeof summary.mismatchPercentage === 'number' ? summary.mismatchPercentage : null;

const drifted = mismatch !== null && mismatch >= VISUAL_DRIFT_PERCENT;

const reasons = [];
if (drifted) {
  // Raw value on purpose - rounding renders a real 0.01% change as "0.0%".
  reasons.push(mismatch + '% of pixels differ from the baseline (band ' + VISUAL_DRIFT_PERCENT + '%)');
  if (summary.sameDimensions === false) reasons.push('page dimensions changed vs the baseline');
}
// A missing percentage is inconclusive, not "fine". Availability was still established by
// stage 1, so the page stays 'up' and the visual half of the check is recorded as unread.
if (mismatch === null) {
  reasons.push('visual check inconclusive - Compare returned no summary.mismatchPercentage');
}

return [
  {
    json: {
      ...stage1,
      state: drifted ? 'visual-drift' : 'up',
      reason: reasons.join(' · '),
      mismatchPercentage: mismatch === null ? '' : mismatch,
      diffLink: (d.diff && d.diff.link) || '',
      visualCheck: mismatch === null ? 'inconclusive' : 'ran',
    },
  },
];

// The solidity core: alert on a STATE TRANSITION, not on every run.
// This workflow runs 144 times a day. Alerting on state instead of on change would send 144
// identical "page is down" messages a day, the channel gets muted, and the next real outage
// is missed. Recoveries are announced too - a monitor that only reports failures never tells
// you it is over.
const VALID = ['up', 'down', 'visual-drift'];
const ICON = { down: '🔴', 'visual-drift': '🟠', up: '✅' };

const r = $input.first().json;
const row = $('Loop Over Watched Pages').first().json;

const previousRaw = String(row.lastState === undefined || row.lastState === null ? '' : row.lastState)
  .trim()
  .toLowerCase();
const previous = VALID.includes(previousRaw) ? previousRaw : '';
const current = String(r.state === undefined || r.state === null ? '' : r.state).trim().toLowerCase();
const checkedAt = new Date().toISOString();

let state = current;
let changed = false;
let transition = '';
let undetermined = false;

if (!VALID.includes(current)) {
  // No state could be determined this run. KEEP the previous value rather than inventing one:
  // overwriting lastState with a guess is exactly how a monitor loses the ability to detect
  // the next real transition (and how a "recovered" alert gets swallowed).
  undetermined = true;
  state = previous;
  transition = previous ? previous + ' (kept - undetermined this run)' : 'undetermined';
} else if (!previous) {
  // First ever check for this row: record the state, and only speak up if it is already bad.
  // Otherwise the first sweep of a 40-page watchlist posts 40 "now up" messages.
  transition = 'first check → ' + current;
  changed = current !== 'up';
} else if (current !== previous) {
  transition = previous + ' → ' + current;
  changed = true;
} else {
  transition = current + ' (unchanged)';
}

const headline =
  state === 'up' && previous && previous !== 'up'
    ? 'Recovered'
    : state === 'down'
      ? 'Down'
      : state === 'visual-drift'
        ? 'Visual drift'
        : 'Status';

// Slack mrkdwn link; falls back to the raw URL when no label was set in the sheet.
const lines = [];
lines.push((ICON[state] || 'ℹ️') + ' *' + headline + '* - <' + r.url + '|' + (r.label || r.url) + '>');
lines.push('Transition: `' + transition + '`');
if (r.reason) lines.push('Reason: ' + r.reason);
if (r.mismatchPercentage !== '' && r.mismatchPercentage !== null && r.mismatchPercentage !== undefined) {
  lines.push('Visual difference: ' + r.mismatchPercentage + '%');
}
if (r.diffLink) lines.push('<' + r.diffLink + '|view diff image>');
if (!r.diffLink && r.screenshotLink) lines.push('<' + r.screenshotLink + '|view capture>');
lines.push('_Checked ' + checkedAt + ' - you get one message per state change, not one per sweep._');

return [
  {
    json: {
      ...r,
      previousState: previous,
      state,
      newLastState: state,
      changed,
      transition,
      undetermined,
      checkedAt,
      alertText: lines.join('\n'),
    },
  },
];
